 lanes.forEach((lane,col)=>{const x=col*240+12;svg.append(svgNode('rect',{x,y:0,width:232,height,rx:5,class:'philosophy-lane'}),svgNode('text',{x:x+12,y:29,class:'philosophy-lane-title'},lane.title),svgNode('text',{x:x+12,y:48,class:'philosophy-lane-range'},cultureRange(lane.range)));lane.personIds.forEach((id,row)=>positions.set(id,{x:x+14,y:70+row*70}));});
 for(const r of relations){const a=positions.get(r.fromId),b=positions.get(r.toId);if(!a||!b)continue;const sx=a.x+196,sy=a.y+24,tx=b.x,ty=b.y+24,same=Math.abs(sx-tx)<220&&Math.floor(a.x/240)===Math.floor(b.x/240);const d=same?`M ${sx} ${sy} C ${sx+34} ${sy}, ${sx+34} ${ty}, ${b.x+196} ${ty}`:`M ${sx} ${sy} C ${sx+65} ${sy}, ${tx-65} ${ty}, ${tx} ${ty}`;const path=svgNode('path',{d,class:'philosophy-edge relation-'+r.type,'marker-end':'url(#philosophy-arrow-'+r.type+')','data-relation-id':r.id});path.setAttribute('role','button');path.setAttribute('tabindex','0');path.setAttribute('aria-label','阅读关系：'+philosophyPerson(r.fromId).name+'到'+philosophyPerson(r.toId).name+'，'+r.title);const readRelation=()=>{const card=root.querySelector(`[data-culture-relation="${r.id}"]`);card?.scrollIntoView({block:'center'});if(card)card.querySelector('.reader-sources').open=true;};path.addEventListener('click',readRelation);path.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();readRelation();}});path.append(svgNode('title',{},philosophyPerson(r.fromId).name+' → '+philosophyPerson(r.toId).name+' · '+r.title));svg.append(path);}
